static inline BOOL rx_scx_member(ULONG id, ULONG cp)
{
    if (id >= sizeof(rx_scx_tables)/sizeof(*rx_scx_tables) || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return FALSE;
    return rx_unicode_member(rx_scx_tables[id].ranges, rx_scx_tables[id].count, cp);
}
