static inline BOOL rx_gc_member(ULONG id, ULONG cp)
{
    if ((id >> 16) == 1) return rx_sc_member(id & 0xffff, cp);
    if ((id >> 16) == 2) return rx_scx_member(id & 0xffff, cp);
    if ((id >> 16) == 3) return rx_bp_member(id & 0xffff, cp);
    if ((id >> 16) == 5) return rx_age_member(id & 0xffff, cp);
    if ((id >> 16) == 6) return rx_gcb_member(id & 0xffff, cp);
    if ((id >> 16) == 7) return rx_sb_member(id & 0xffff, cp);
    if ((id >> 16) == 8) return rx_wb_member(id & 0xffff, cp);
    if ((id >> 16) == 4) {
        if (cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return FALSE;
        if ((id & 0xffff) == 0) return TRUE;
        if ((id & 0xffff) == 1) return cp < 128;
        if ((id & 0xffff) == 2) return !rx_unicode_member(rx_gc_Unassigned, sizeof(rx_gc_Unassigned)/sizeof(*rx_gc_Unassigned), cp);
        return FALSE;
    }
    if (id >= sizeof(rx_gc_tables)/sizeof(*rx_gc_tables) || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) return FALSE;
    return rx_unicode_member(rx_gc_tables[id].ranges, rx_gc_tables[id].count, cp);
}
